/**
 * Rust extraction. HEURISTIC, NOT A PARSER: there is no Rust parser in the standard toolchain
 * we can call, so this scanner works line by line. It strips comments and string literals,
 * tracks brace depth, and reports only items at the top level of a file, inside `impl` and
 * `trait` blocks (their `fn`, `const` and `type` items), and inside inline `mod` blocks.
 * Known misses: items generated by macros (`macro_rules!` bodies and macro invocations), items
 * nested in function bodies, raw strings that span lines are handled only approximately, and
 * `#[cfg]` is ignored. Use statements are recorded as imports, one per expanded path.
 */
import type { ImportRecord } from "../extract.js";
import type { SymbolInput } from "../types.js";
import { type FileExtraction, MAX_DOC_LENGTH, type SymbolDraft, makeSymbol } from "./common.js";

interface LexState {
  block: number;
  inString: boolean;
  raw: number | undefined;
}

/** Replaces comments and string/char literal contents with spaces, keeping columns. */
function stripLine(line: string, state: LexState): string {
  let out = "";
  let i = 0;
  while (i < line.length) {
    if (state.block > 0) {
      if (line.startsWith("*/", i)) {
        state.block--;
        out += "  ";
        i += 2;
      } else if (line.startsWith("/*", i)) {
        state.block++;
        out += "  ";
        i += 2;
      } else {
        out += " ";
        i++;
      }
      continue;
    }
    if (state.inString) {
      if (line[i] === "\\") {
        out += "  ";
        i += 2;
        continue;
      }
      if (line[i] === '"') {
        state.inString = false;
      }
      out += " ";
      i++;
      continue;
    }
    if (state.raw !== undefined) {
      const close = `"${"#".repeat(state.raw)}`;
      if (line.startsWith(close, i)) {
        state.raw = undefined;
        out += " ".repeat(close.length);
        i += close.length;
      } else {
        out += " ";
        i++;
      }
      continue;
    }
    if (line.startsWith("//", i)) {
      break;
    }
    if (line.startsWith("/*", i)) {
      state.block = 1;
      out += "  ";
      i += 2;
      continue;
    }
    const previous = line[i - 1];
    const raw = /^r(#*)"/.exec(line.slice(i));
    if (raw !== null && (previous === undefined || !/\w/.test(previous))) {
      state.raw = raw[1]?.length ?? 0;
      out += " ".repeat(raw[0].length);
      i += raw[0].length;
      continue;
    }
    if (line[i] === '"') {
      state.inString = true;
      out += " ";
      i++;
      continue;
    }
    if (line[i] === "'") {
      const char = /^'(?:\\[^']*|[^\\'])'/.exec(line.slice(i));
      if (char !== null) {
        out += " ".repeat(char[0].length);
        i += char[0].length;
        continue;
      }
    }
    out += line[i];
    i++;
  }
  return out;
}

/**
 * Item headers: optional visibility, qualifiers, then the item keyword. Matched against code
 * with comments and string contents already blanked.
 */
const ITEM =
  /^(pub(?:\s*\([^)]*\))?\s+)?(?:(?:default|const|async|unsafe|extern)\s+)*(fn|struct|enum|union|trait|impl|mod|type|const|static|use)\b(.*)$/;

interface Header {
  readonly text: string;
  readonly endLine: number;
  readonly terminator: "{" | ";" | "end";
}

interface Frame {
  readonly kind: "impl" | "trait" | "mod";
  readonly name: string;
  readonly exported: boolean;
  readonly innerDepth: number;
}

const MAX_HEADER_LINES = 30;

/** Expands `use a::{b, c::d as e, self}` into full paths. Aliases and globs are dropped. */
export function expandUse(body: string): string[] {
  const open = body.indexOf("{");
  if (open < 0) {
    const plain = body
      .replace(/\s+as\s+\w+\s*$/, "")
      .replace(/::\*\s*$/, "")
      .replace(/\s+/g, "")
      .trim();
    return plain.length > 0 ? [plain] : [];
  }
  let depth = 0;
  let close = body.length;
  for (let i = open; i < body.length; i++) {
    if (body[i] === "{") {
      depth++;
    } else if (body[i] === "}") {
      depth--;
      if (depth === 0) {
        close = i;
        break;
      }
    }
  }
  const prefix = body
    .slice(0, open)
    .replace(/::\s*$/, "")
    .replace(/\s+/g, "");
  const parts: string[] = [];
  let current = "";
  let level = 0;
  for (const ch of body.slice(open + 1, close)) {
    if (ch === "{") {
      level++;
    } else if (ch === "}") {
      level--;
    }
    if (ch === "," && level === 0) {
      parts.push(current);
      current = "";
    } else {
      current += ch;
    }
  }
  parts.push(current);
  const out: string[] = [];
  for (const part of parts) {
    const item = part.trim();
    if (item.length === 0) {
      continue;
    }
    if (item === "self") {
      if (prefix.length > 0) {
        out.push(prefix);
      }
      continue;
    }
    out.push(...expandUse((prefix.length > 0 ? `${prefix}::` : "") + item));
  }
  return out;
}

/** Name of the type an `impl` block is for: `impl<T> Trait for Foo<T>` gives `Foo`. */
export function implOwner(header: string): string {
  let rest = "";
  let depth = 0;
  for (const ch of header.replace(/^impl\b/, "")) {
    if (ch === "<") {
      depth++;
    } else if (ch === ">") {
      depth = Math.max(0, depth - 1);
    } else if (depth === 0) {
      rest += ch;
    }
  }
  rest = rest.split(/\bwhere\b/)[0] ?? "";
  const forAt = rest.search(/\bfor\b/);
  const target = (forAt >= 0 ? rest.slice(forAt + 3) : rest)
    .trim()
    .replace(/^[&\s]*(?:mut\s+|dyn\s+)*/, "");
  const last = target.split("::").pop() ?? "";
  return /^[A-Za-z_]\w*/.exec(last.trim())?.[0] ?? "";
}

/** Splits `text` on the first `;` or `{` (when braces end headers) outside parentheses. */
function readHeader(
  lines: readonly string[],
  code: readonly string[],
  start: number,
  startColumn: number,
  braceEnds: boolean,
): Header {
  let text = "";
  let parens = 0;
  for (let line = start; line < code.length && line < start + MAX_HEADER_LINES; line++) {
    const source = code[line] ?? "";
    const raw = lines[line] ?? "";
    const from = line === start ? startColumn : 0;
    for (let i = from; i < source.length; i++) {
      const ch = source[i] ?? "";
      if (ch === "(" || ch === "[") {
        parens++;
      } else if (ch === ")" || ch === "]") {
        parens = Math.max(0, parens - 1);
      } else if (parens === 0 && (ch === ";" || (braceEnds && ch === "{"))) {
        return { text, endLine: line, terminator: ch };
      }
      // Termination is decided on the blanked code; the text keeps the raw characters.
      text += raw[i] ?? ch;
    }
    text += " ";
  }
  return { text, endLine: Math.min(code.length, start + MAX_HEADER_LINES) - 1, terminator: "end" };
}

export function extractRust(text: string): FileExtraction {
  const lines = text.split(/\r?\n/);
  const state: LexState = { block: 0, inString: false, raw: undefined };
  const code = lines.map((line) => stripLine(line, state));

  const depthStart: number[] = [];
  const depthAfter: number[] = [];
  let depth = 0;
  for (const line of code) {
    depthStart.push(depth);
    for (const ch of line) {
      if (ch === "{") {
        depth++;
      } else if (ch === "}") {
        depth = Math.max(0, depth - 1);
      }
    }
    depthAfter.push(depth);
  }

  const endOf = (start: number, header: Header): number => {
    if (header.terminator === ";") {
      return header.endLine;
    }
    const base = depthStart[start] ?? 0;
    for (let k = header.endLine; k < code.length; k++) {
      if ((depthAfter[k] ?? 0) <= base) {
        return k;
      }
    }
    return code.length - 1;
  };

  const docAbove = (index: number): string => {
    const doc: string[] = [];
    let k = index - 1;
    while (k >= 0) {
      const line = (lines[k] ?? "").trim();
      if (line.startsWith("#[") || line.startsWith("#![")) {
        k--;
        continue;
      }
      if (line.startsWith("///") && !line.startsWith("////")) {
        doc.unshift(line.slice(3).replace(/^ /, ""));
        k--;
        continue;
      }
      break;
    }
    return doc.join("\n").slice(0, MAX_DOC_LENGTH);
  };

  const symbols: SymbolInput[] = [];
  const imports: ImportRecord[] = [];
  const stack: Frame[] = [];
  const modPath = (): string[] => stack.filter((f) => f.kind === "mod").map((f) => f.name);
  let skipUntil = -1;

  for (let i = 0; i < code.length; i++) {
    while (stack.length > 0 && (depthStart[i] ?? 0) < (stack[stack.length - 1]?.innerDepth ?? 0)) {
      stack.pop();
    }
    const container = stack[stack.length - 1];
    const level = container?.innerDepth ?? 0;
    if (i <= skipUntil || (depthStart[i] ?? 0) !== level) {
      continue;
    }
    const source = code[i] ?? "";
    const column = source.length - source.trimStart().length;
    const match = ITEM.exec(source.trimStart());
    if (match === null) {
      continue;
    }
    const isPub = match[1] !== undefined;
    const keyword = match[2] ?? "";
    const rest = match[3] ?? "";

    if (keyword === "use") {
      const header = readHeader(lines, code, i, column, false);
      skipUntil = header.endLine;
      const body = header.text.replace(/^\s*(?:pub(?:\s*\([^)]*\))?\s+)?use\s+/, "");
      for (const path of expandUse(body)) {
        imports.push({ specifier: path, bindings: [] });
      }
      continue;
    }

    const header = readHeader(lines, code, i, column, true);
    skipUntil = header.endLine;
    const signature = header.text.trim();
    const end = endOf(i, header) + 1;
    const doc = docAbove(i);
    const name = /^(?:mut\s+)?([A-Za-z_]\w*)/.exec(rest.trim())?.[1];
    const owner = container !== undefined && container.kind !== "mod" ? container : undefined;
    const prefix = modPath();
    const withOwner = (leaf: string): string =>
      [...prefix, ...(owner !== undefined ? [owner.name] : []), leaf].join(".");
    const push = (draft: SymbolDraft): void => {
      symbols.push(makeSymbol(draft, lines));
    };

    switch (keyword) {
      case "impl": {
        stack.push({
          kind: "impl",
          name: implOwner(signature),
          exported: false,
          innerDepth: (depthStart[header.endLine] ?? 0) + 1,
        });
        break;
      }
      case "trait":
      case "mod": {
        if (name === undefined) {
          break;
        }
        const kind = keyword === "trait" ? "interface" : "module";
        if (header.terminator === "{") {
          push({
            name,
            qualified: withOwner(name),
            kind,
            startLine: i + 1,
            endLine: end,
            signature,
            doc,
            exported: isPub,
          });
          stack.push({
            kind: keyword === "trait" ? "trait" : "mod",
            name,
            exported: isPub,
            innerDepth: (depthStart[header.endLine] ?? 0) + 1,
          });
          break;
        }
        if (keyword === "mod") {
          imports.push({ specifier: `mod ${name}`, bindings: [] });
        }
        push({
          name,
          qualified: withOwner(name),
          kind,
          startLine: i + 1,
          endLine: end,
          signature,
          doc,
          exported: isPub,
        });
        break;
      }
      case "fn": {
        if (name === undefined || (owner !== undefined && owner.name === "")) {
          break;
        }
        const exported = isPub || (owner?.kind === "trait" && owner.exported);
        push({
          name,
          qualified: withOwner(name),
          kind: owner !== undefined ? "method" : "function",
          startLine: i + 1,
          endLine: end,
          signature,
          doc,
          exported,
        });
        break;
      }
      case "struct":
      case "union":
      case "enum":
      case "type":
      case "const":
      case "static": {
        if (name === undefined || (owner !== undefined && owner.name === "")) {
          break;
        }
        const kind =
          keyword === "enum"
            ? "enum"
            : keyword === "struct" || keyword === "union"
              ? "class"
              : keyword === "type"
                ? "type"
                : keyword === "const"
                  ? "const"
                  : "var";
        push({
          name,
          qualified: withOwner(name),
          kind,
          startLine: i + 1,
          endLine: end,
          signature,
          doc,
          exported: isPub || (owner?.kind === "trait" && owner.exported),
        });
        break;
      }
      default:
        break;
    }
  }

  return { result: { symbols, imports, calls: [] } };
}
